// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;
    function setUp() public { c = new PENNY_BY_PENNY(); }
    function testFuzz_property(uint256 initialMinSum, uint256 newMinSum) public {
        vm.assume(initialMinSum != newMinSum);

        c.SetMinSum(initialMinSum);
        c.Initialized();

        uint256 minBefore = c.MinSum();

        bool reverted;
        try c.SetMinSum(newMinSum) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 minAfter = c.MinSum();

        assertTrue(reverted || minAfter == minBefore);
    }
}
